// SECURITY LAYER 1: Country Code Filter
const input = $input.first().json;
const phone = input.phoneNumberFormatted;

const ALLOWED_COUNTRY_CODES = ['91','61'];
const isAllowedCountry = ALLOWED_COUNTRY_CODES.some(code => phone.startsWith(code));

if (!isAllowedCountry) {
  return [{ json: { ...input, securityCheck: 'REJECTED', rejectReason: 'country_not_allowed', silent: true } }];
}

return [{ json: { ...input, securityCheck: 'PASSED_COUNTRY', countryCode: phone.substring(0, 3) } }];

// WF-01: Prepare User Data
// Prepares all data needed for WF-02 routing
const securityData = $('Layer 3 : Blacklisted Users Filter').first().json;
const userResult = $('Load User').first().json;

// ── Pending user lookup ───────────────────────────────────────────────────────
let pendingUserData = null;
try {
  const pendingResult = $('Load Pending User').first().json;
  if (pendingResult && pendingResult.phone_number) {
    pendingUserData = {
      phoneNumber: pendingResult.phone_number,
      contactName: pendingResult.contact_name,
      createdAt: pendingResult.created_at
    };
  }
} catch(e) {
  // Node may not have run or returned no rows — treat as null
}

// ── User lookup ───────────────────────────────────────────────────────────────
const userExists = userResult && userResult.id;
let userData = null;
if (userExists) {
  let contextObj = {};
  try {
    contextObj = typeof userResult.context === 'string'
      ? JSON.parse(userResult.context)
      : (userResult.context || {});
  } catch(e) {
    console.error('Error parsing user context:', e);
  }
  userData = {
    id: userResult.id,
    phoneNumber: userResult.phone_number,
    name: userResult.name,
    dateOfBirth: userResult.date_of_birth,
    timeOfBirth: userResult.time_of_birth,
    placeOfBirth: userResult.place_of_birth,
    status: userResult.status,
    currentConsultationId: userResult.current_consultation_id,
    slackChannelId: userResult.slack_channel_id,
    totalConsultations: userResult.total_consultations,
    context: contextObj,
    createdAt: userResult.created_at,
    updatedAt: userResult.updated_at,
    lastMessageAt: userResult.last_message_at,
    awaitingFeedback: userResult.awaiting_feedback,
    blockedAt: userResult.blocked_at,
    blockedBy: userResult.blocked_by,
    blockedReason: userResult.blocked_reason
  };
}

// ── Return combined data for WF-02 ────────────────────────────────────────────
return [{ json: {
  messageId: securityData.messageId,
  phoneNumber: securityData.phoneNumber,
  phoneNumberFormatted: securityData.phoneNumberFormatted,
  contactName: securityData.contactName,
  messageType: securityData.messageType,
  messageContent: securityData.messageContent,
  messageContentUpper: securityData.messageContentUpper,
  rawMessage: securityData.rawMessage,
  timestamp: securityData.timestamp,
  metadata: securityData.metadata,

  // User state
  isNewUser: !userExists && !pendingUserData,
  user: userData,
  pendingUser: pendingUserData
} }];

// Node: Filter Message Types
const input = $input.first().json;
const messageType = input.messageType; // From WhatsApp webhook

// Allowed types for Chinmay Astro
const ALLOWED_TYPES = [
  'text',           // Regular text messages
  'interactive'     // Form submissions, button responses
];

// Check if message type is allowed
const isAllowed = ALLOWED_TYPES.includes(messageType);

return [{ json: {
  ...input,
  messageTypeAllowed: isAllowed,
  messageTypeReason: isAllowed ? 'Allowed type' : `Rejected type: ${messageType}`
} }];

const input = $('Layer 2: Non-Text Message Filter').first().json;
const blacklistResult = $input.first().json;

if (blacklistResult && blacklistResult.id) {
  if (blacklistResult.status === 'opted_out') {
    return [{ json: { ...input, securityCheck: 'OPTED_OUT', rejectReason: 'opted_out', silent: true } }];
  }
  return [{ json: { ...input, securityCheck: 'REJECTED', rejectReason: 'blacklisted', silent: true } }];
}

return [{ json: { ...input, securityCheck: 'PASSED_BLACKLIST' } }];

// WF-01: Build canonical core envelope (§2.1 data-contract-discipline-phase-1)
// Emits a slim, stable shape consumed by WF-02, WF-21, and all downstream leaves.
// The existing 20-column users SELECT (Load User) is preserved upstream;
// this node projects only the §2.1 required fields onto the envelope.

const d = $input.first().json;

const phoneNumber   = d.phoneNumber   || null;
const messageType   = d.messageType   || null;
const messageContent = d.messageContent ?? null;

let userEnv = null;
if (d.user && d.user.id != null) {
  userEnv = {
    id:                   d.user.id,
    phone_number:         d.user.phoneNumber || phoneNumber,
    name:                 d.user.name        || null,
    status:               d.user.status      || null,
    slack_channel_id:     d.user.slackChannelId     || null,
    current_consultation_id: d.user.currentConsultationId || null
  };
}

let pendingUserEnv = null;
if (d.pendingUser && d.pendingUser.phoneNumber) {
  pendingUserEnv = {
    id:           d.pendingUser.id           || null,
    contact_name: d.pendingUser.contactName  || null
  };
}

return [{ json: {
  phoneNumber,
  messageType,
  messageContent,
  user:        userEnv,
  pendingUser: pendingUserEnv,

  routing:             d.routing             || null,
  messageContentUpper: d.messageContentUpper ?? null,
  messageId:           d.messageId           || null,
  contactName:         d.contactName         || null,
  rawMessage:          d.rawMessage          || null,
  timestamp:           d.timestamp           || null,
  metadata:            d.metadata            || null,
  isNewUser:           d.isNewUser           != null ? d.isNewUser : (!userEnv && !pendingUserEnv)
} }];

